/* DoorLock: table-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "DoorLock.h"

/* Internal functions */
static size_t RegionOf(Security_DoorLock_State state);
static size_t FirstRegionOf(Security_DoorLock_State state);
static size_t RegionsOf(Security_DoorLock_State state);
static void Entry_Locked(Security_DoorLock* m);
static void Entry_Unlocked(Security_DoorLock* m);
static void Entry_Alarm(Security_DoorLock* m);
static void Exit_Alarm(Security_DoorLock* m);
static void OnEntry(Security_DoorLock* m, Security_DoorLock_State state);
static void OnExit(Security_DoorLock* m, Security_DoorLock_State state);
static Security_DoorLock_State Innermost(const Security_DoorLock* m, Security_DoorLock_State state);
static void ExitState(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterState(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterRegion(Security_DoorLock* m, size_t region);
static void EnterDefault(Security_DoorLock* m, Security_DoorLock_State state);
static void EnterDown(Security_DoorLock* m, Security_DoorLock_State from, Security_DoorLock_State target);
static bool Guard_0(Security_DoorLock* m);
static void Transition_0(Security_DoorLock* m);
static bool Guard_1(Security_DoorLock* m);
static void Transition_2(Security_DoorLock* m);
static bool Guard_5(Security_DoorLock* m);
static void Transition_5(Security_DoorLock* m);
static bool HandleEvent(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event);
static bool DispatchState(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event);
static bool DispatchCore(Security_DoorLock* m, Security_DoorLock_Event event);

static const Security_DoorLock_State kParent[Security_DoorLock_StateCount] = {
    Security_DoorLock_State_None,   /* Locked */
    Security_DoorLock_State_None,   /* Unlocked */
    Security_DoorLock_State_None,   /* Alarm */
};
static const unsigned char kRegionOf[Security_DoorLock_StateCount] =   /* region that contains the state */ {
    0,   /* Locked */
    0,   /* Unlocked */
    0,   /* Alarm */
};
static const unsigned char kFirstRegion[Security_DoorLock_StateCount] =   /* first own region */ {
    0,   /* Locked */
    0,   /* Unlocked */
    0,   /* Alarm */
};
static const unsigned char kRegionsOf[Security_DoorLock_StateCount] =   /* number of own regions */ {
    0,   /* Locked */
    0,   /* Unlocked */
    0,   /* Alarm */
};
static const char* const kStateNames[Security_DoorLock_StateCount] = {
    "Locked",   /* Locked */
    "Unlocked",   /* Unlocked */
    "Alarm",   /* Alarm */
};
static const char* const kEventNames[Security_DoorLock_EventCount] = {
    "EnterCode",
    "Lock",
    "Timeout",
    "Reset",
};

static size_t RegionOf(Security_DoorLock_State state) {
    return kRegionOf[state];
}

static size_t FirstRegionOf(Security_DoorLock_State state) {
    return kFirstRegion[state];
}

static size_t RegionsOf(Security_DoorLock_State state) {
    return kRegionsOf[state];
}

Security_DoorLock_State Security_DoorLock_ParentOf(Security_DoorLock_State state) {
    return state == Security_DoorLock_State_None ? Security_DoorLock_State_None : kParent[state];
}

const char* Security_DoorLock_StateName(Security_DoorLock_State state) {
    return state == Security_DoorLock_State_None ? "None" : kStateNames[state];
}

const char* Security_DoorLock_EventName(Security_DoorLock_Event event) {
    return kEventNames[event];
}

typedef void (*Handler)(Security_DoorLock* m);

static void Entry_Locked(Security_DoorLock* m) {
    m->hooks->engageBolt(m->context);
}

static void Entry_Unlocked(Security_DoorLock* m) {
    m->hooks->releaseBolt(m->context);
}

static void Entry_Alarm(Security_DoorLock* m) {
    m->hooks->sirenOn(m->context);
}

static void Exit_Alarm(Security_DoorLock* m) {
    m->hooks->sirenOff(m->context);
}

static const Handler kEntry[Security_DoorLock_StateCount] = {
    Entry_Locked,   /* Locked */
    Entry_Unlocked,   /* Unlocked */
    Entry_Alarm,   /* Alarm */
};
static const Handler kExit[Security_DoorLock_StateCount] = {
    NULL,   /* Locked */
    NULL,   /* Unlocked */
    Exit_Alarm,   /* Alarm */
};
static void OnEntry(Security_DoorLock* m, Security_DoorLock_State state) {
    if (kEntry[state] != NULL) {
        kEntry[state](m);
    }
}

static void OnExit(Security_DoorLock* m, Security_DoorLock_State state) {
    if (kExit[state] != NULL) {
        kExit[state](m);
    }
}

static Security_DoorLock_State Innermost(const Security_DoorLock* m, Security_DoorLock_State state) {
    while (state != Security_DoorLock_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Security_DoorLock_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Security_DoorLock* m, Security_DoorLock_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Security_DoorLock_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    OnExit(m, state);
    m->active[RegionOf(state)] = Security_DoorLock_State_None;
}

static void EnterState(Security_DoorLock* m, Security_DoorLock_State state) {
    m->active[RegionOf(state)] = state;
    OnEntry(m, state);
}

static void EnterRegion(Security_DoorLock* m, size_t region) {
    (void)m;
    (void)region;
}

static void EnterDefault(Security_DoorLock* m, Security_DoorLock_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterDown(Security_DoorLock* m, Security_DoorLock_State from, Security_DoorLock_State target) {
    Security_DoorLock_State state = target;
    Security_DoorLock_State next = Security_DoorLock_State_None;
    while (Security_DoorLock_ParentOf(state) != from) {
        next = state;
        state = Security_DoorLock_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Security_DoorLock_State_None) {
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target);
}

typedef bool (*GuardFn)(Security_DoorLock* m);

static bool Guard_0(Security_DoorLock* m) {
    return m->hooks->isValidCode(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
}

static void Transition_0(Security_DoorLock* m) {
    m->hooks->resetAttempts(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
}

static bool Guard_1(Security_DoorLock* m) {
    return m->hooks->tooManyAttempts(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
}

static void Transition_2(Security_DoorLock* m) {
    m->hooks->countFailure(m->context, ((const Security_DoorLock_EnterCodeArgs*)m->args)->code);
}

static bool Guard_5(Security_DoorLock* m) {
    return m->hooks->isAdminCode(m->context, ((const Security_DoorLock_ResetArgs*)m->args)->code);
}

static void Transition_5(Security_DoorLock* m) {
    m->hooks->resetAttempts(m->context, ((const Security_DoorLock_ResetArgs*)m->args)->code);
}

typedef struct {
    Security_DoorLock_State source;
    Security_DoorLock_Event event;
    GuardFn guard;
    Handler action;
    Security_DoorLock_State target;   /* None for internal transitions */
    Security_DoorLock_State lca;
} TransitionRow;

/* source, event, guard, action, target, least common ancestor */
static const TransitionRow kTransitions[6] = {
    { Security_DoorLock_State_Locked, Security_DoorLock_Event_EnterCode, Guard_0, Transition_0, Security_DoorLock_State_Unlocked, Security_DoorLock_State_None },
    { Security_DoorLock_State_Locked, Security_DoorLock_Event_EnterCode, Guard_1, NULL, Security_DoorLock_State_Alarm, Security_DoorLock_State_None },
    { Security_DoorLock_State_Locked, Security_DoorLock_Event_EnterCode, NULL, Transition_2, Security_DoorLock_State_None, Security_DoorLock_State_None },
    { Security_DoorLock_State_Unlocked, Security_DoorLock_Event_Lock, NULL, NULL, Security_DoorLock_State_Locked, Security_DoorLock_State_None },
    { Security_DoorLock_State_Unlocked, Security_DoorLock_Event_Timeout, NULL, NULL, Security_DoorLock_State_Locked, Security_DoorLock_State_None },
    { Security_DoorLock_State_Alarm, Security_DoorLock_Event_Reset, Guard_5, Transition_5, Security_DoorLock_State_Locked, Security_DoorLock_State_None },
};

static bool TryRow(Security_DoorLock* m, const TransitionRow* row) {
    if (row->guard != NULL && !row->guard(m)) {
        return false;
    }
    if (row->target == Security_DoorLock_State_None) {
        if (row->action != NULL) {
            row->action(m);
        }
        return true;
    }
    Security_DoorLock_State root = row->source;
    while (Security_DoorLock_ParentOf(root) != row->lca) {
        root = Security_DoorLock_ParentOf(root);
    }
    ExitState(m, root);
    if (row->action != NULL) {
        row->action(m);
    }
    EnterDown(m, row->lca, row->target);
    return true;
}

static bool HandleEvent(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event) {
    size_t i;
    for (i = 0; i < 6; ++i) {
        if (kTransitions[i].source == state && kTransitions[i].event == event && TryRow(m, &kTransitions[i])) {
            return true;
        }
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Security_DoorLock* m, Security_DoorLock_State state, Security_DoorLock_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Security_DoorLock_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Security_DoorLock* m, Security_DoorLock_Event event) {
    if (m->active[0] != Security_DoorLock_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    return false;
}

void Security_DoorLock_Init(Security_DoorLock* m, const Security_DoorLock_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Security_DoorLock_RegionCount; ++i) {
        m->active[i] = Security_DoorLock_State_None;
    }
    m->args = NULL;
}

void Security_DoorLock_Start(Security_DoorLock* m) {
    size_t i;
    m->hooks->Lock(m->context);
    for (i = 0; i < Security_DoorLock_RegionCount; ++i) {
        m->active[i] = Security_DoorLock_State_None;
    }
    EnterDown(m, Security_DoorLock_State_None, Security_DoorLock_State_Locked);
    m->hooks->Unlock(m->context);
}

bool Security_DoorLock_Dispatch(Security_DoorLock* m, Security_DoorLock_Event event) {
    bool handled = false;
    m->hooks->Lock(m->context);
    if (event != Security_DoorLock_Event_EnterCode && event != Security_DoorLock_Event_Reset) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
    }
    m->hooks->Unlock(m->context);
    return handled;
}

bool Security_DoorLock_DispatchEnterCode(Security_DoorLock* m, int code) {
    bool handled;
    Security_DoorLock_EnterCodeArgs args;
    args.code = code;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Security_DoorLock_Event_EnterCode);
    m->args = NULL;
    m->hooks->Unlock(m->context);
    return handled;
}

bool Security_DoorLock_DispatchReset(Security_DoorLock* m, int code) {
    bool handled;
    Security_DoorLock_ResetArgs args;
    args.code = code;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Security_DoorLock_Event_Reset);
    m->args = NULL;
    m->hooks->Unlock(m->context);
    return handled;
}

Security_DoorLock_State Security_DoorLock_Current(const Security_DoorLock* m) {
    Security_DoorLock_State result;
    m->hooks->Lock(m->context);
    result = Innermost(m, m->active[0]);
    m->hooks->Unlock(m->context);
    return result;
}

bool Security_DoorLock_IsIn(const Security_DoorLock* m, Security_DoorLock_State state) {
    bool result;
    m->hooks->Lock(m->context);
    result = state != Security_DoorLock_State_None && m->active[RegionOf(state)] == state;
    m->hooks->Unlock(m->context);
    return result;
}

bool Security_DoorLock_IsFinished(const Security_DoorLock* m) {
    bool result;
    m->hooks->Lock(m->context);
    result = ((void)m, false);
    m->hooks->Unlock(m->context);
    return result;
}

